"""Registrar leituras e inspeção visual do lote B3-01 (registro 125)."""
from pathlib import Path
from collections import Counter
import json,hashlib
A=Path(__file__).resolve().parent;R=A.parents[1]
def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,d):(A/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
m=load(A/'amostra.json');changes=load(A/'alteracoes.json');ins=load(A/'imagens-inspecionadas-primeira-prova-visual.json')['primeira_prova'];N=len(m['paginas']);assert N==11
cur={i:sha(A/f'pagina-{i:02}.png') for i in range(1,N+1)};same={i for i in cur if ins[str(i)]==cur[i]};assert same==set(range(1,12))-{4},same
notes={1:'Abertura do reparo, Ofício, atendimento de Ena e quadro da conta.',2:'Fim do reparo com quadro das Classes; abertura da Restrição corporal na mesma página.',3:'Ficha de Nilo em quadro largo; participar à distância.',4:'Situação de uso, corpo presente e quadro de cuidados por condição.',5:'Cuidados de cada condição e registro; abertura dos pareceres na mesma página.',6:'Toque, Prender com fios e informação de objeto.',7:'Vibrações, imunidade, aposta e menores de Origem.',8:'Restrições; abertura dos poderes avançados e começo do quadro Liberação/Técnica Máxima.',9:'Quadro com cabeçalho repetido; Liberação e Máximas de dano e cura.',10:'Máxima de utilidade, recarga e Domínio; Galeria de Vidro.',11:'Galeria, Sala de Trégua e CE4 da Restrição corporal.'}
save('revisao-final.json',{'registro':125,'pdf':m['pdf'],'pdf_sha256':m['pdf_sha256'],'passagens_textuais':[{'passagem':1,'registros':sum(c['passagem']==1 for c in changes),'escopo':'Leitura integral das quatro fontes e das regras citadas, quatro cópias, remissões e clareza.'},{'passagem':2,'registros':sum(c['passagem']==2 for c in changes),'escopo':'Leitura integral das onze páginas da prova e pente fino.'}],'ajuste_de_diagramacao':'Casos curtos seguem na mesma página, como no B2-06; quadros a partir de cinco linhas podem continuar com cabeçalho repetido.','paginas':[{'pagina':i,'imagem':str((A/f'pagina-{i:02}.png').relative_to(R)),'imagem_sha256':cur[i],'inspecionada':True,'metodo':'Inspeção direta após o último ajuste' if i==4 else 'Inspeção direta na primeira prova; imagem idêntica (mesmo hash)','observacao':notes[i]} for i in range(1,N+1)],'limites':['Sem leitor humano independente ou terceira leitura integral.','Uma linha do quadro de Liberação e Técnica Máxima fica no fim da página 8; reavaliar na integração.','Não conclui a revisão visual global ou a comparação final do livro inteiro.']})
ranges={'s090':[1,2],'s091':[2,5],'s030':[5,8],'s031':[8,11]};rows=[]
for f in m['fontes']:
 counts=Counter(str(c['passagem']) for c in changes if c['fonte']==f['fonte']);rows.append({'id':f['fonte_id'],'fonte_original':f['fonte_original'],'fonte_revisada':f['fonte'],'sha256_original':f['sha256_original'],'sha256_revisado':f['sha256'],'passagem_1':'Original integral e regras pertinentes consultados.','passagem_2_paginas_da_prova':ranges[f['fonte_id']],'paginas_na_prova_final':ranges[f['fonte_id']],'registros_por_passagem':dict(counts),'estado':'duas passagens locais; conferir conjunto antes de integrar'})
save('leitura-por-caso.json',{'registro':125,'casos':rows,'limites':'Sem terceira leitura integral, teste humano ou nova simulação.'})
save('mapa-do-lote.json',{'registro':125,'lote':'B3-01','casos':[f['fonte_id'] for f in m['fontes']],'pdf_parcial':m['pdf'],'paginas':N,'casos_revistos_total':37,'casos_pendentes':22,'lotes_pendentes':5,'consultas_complementares_pendentes':17,'etapa_6':'em andamento','proximo_lote':'B3-02','modelo_recomendado':'Claude Opus 5.5 (equivalente no plano: GPT-6.1 Sol)','esforco_recomendado':'alto','edicao_integrada':'preservada; não substituída'})
print(json.dumps({'paginas_inspecionadas':N,'registros':len(changes),'casos':4},ensure_ascii=False))
